import{_ as p,a0 as i,w as l,s as u,ao as e,I as o,x as n,a1 as a,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"管理 crontab 的开源工具 | LCTT x X-CMD","titleTemplate":false,"description":"管理 crontab 的开源工具 | LCTT (202205) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"管理 crontab 的开源工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"管理 crontab 的开源工具 | LCTT (202205) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202205/20220506 My favorite open source tool for using crontab","title":"管理 crontab 的开源工具","tag":"202205","desc":""},"relativePath":"202205/20220506 My favorite open source tool for using crontab.md","filePath":"[post].md"}'),b={name:"202205/20220506 My favorite open source tool for using crontab.md"};function d(m,t,f,g,T,c){const r=i("Link");return l(),u("div",null,[t[27]||(t[27]=e('<h1 id="管理-crontab-的开源工具" tabindex="-1">管理 crontab 的开源工具 <a class="header-anchor" href="#管理-crontab-的开源工具" aria-label="Permalink to “管理 crontab 的开源工具”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202205/16/100309tw6wgx3sss36wl6r.jpg" alt=""></p><blockquote><p>crontab-ui 是一个用 Node.js 编写的 Web 前端，帮助管理 crontab 文件。</p></blockquote><p><em>自动化是目前的一个热门话题。在我作为网站可靠性工程师（SRE）的日常工作中，我的部分职责是将尽可能多的重复性任务自动化。但是，有多少人在我们的日常非工作生活中这样做呢？今年，我专注于将劳作自动化，以便我们可以专注于重要的事情。</em></p><p>作为一个初出茅庐的系统管理员，我最早了解的东西之一是 “cron”。cron 被广泛用于做一些事情，如轮换日志、启动和停止服务、运行程序作业等等。它在几乎所有的 Unix 和 Linux 系统中都可用，而且是我认识的每个系统管理员用来帮助管理服务和服务器的东西。cron 可以自动运行任何控制台应用或脚本，这使得它非常、非常灵活。</p><blockquote><p>LCTT 译注：CRON 是 “Command Run On” 的缩写，即在某个时间运行命令。</p></blockquote><p><img src="https://opensource.com/sites/default/files/2022-04/Day01-1.png" alt="Image of a Crontab"></p><p>我用 cron 来获取电子邮件，运行过滤程序，确保服务正在运行，与 Habitica 等在线游戏互动等。</p><h3 id="以传统方式使用-cron" tabindex="-1">以传统方式使用 cron <a class="header-anchor" href="#以传统方式使用-cron" aria-label="Permalink to “以传统方式使用 cron”">​</a></h3>',9)),o("p",null,[t[1]||(t[1]=n("要开始使用 cron，你可以简单地在命令行输入 ",-1)),t[2]||(t[2]=o("code",null,"crontab -e",-1)),t[3]||(t[3]=n("，启动一个打开了当前 ",-1)),t[4]||(t[4]=o("code",null,"crontab",-1)),t[5]||(t[5]=n("（“cron table” 的缩写）文件的编辑器（如果你以 root 身份这样做，你访问的是系统 crontab）。这是保存作业计划的地方，记录了何时运行。David Both 已经写了 ",-1)),a(r,{href:"https://opensource.com/article/17/11/how-use-cron-linux"},{default:s(()=>[...t[0]||(t[0]=[n("大量",-1)])]),_:1}),t[6]||(t[6]=n(" 关于该文件的格式和如何使用它的文章，所以我不打算在这里介绍。我要说的是，对于新用户来说，这可能有点吓人，而且设置时间有点痛苦。",-1))]),t[28]||(t[28]=o("h3",{id:"介绍-crontab-ui",tabindex:"-1"},[n("介绍 crontab-ui "),o("a",{class:"header-anchor",href:"#介绍-crontab-ui","aria-label":"Permalink to “介绍 crontab-ui”"},"​")],-1)),o("p",null,[t[8]||(t[8]=n("有一些奇妙的工具可以帮助解决这个问题。我最喜欢的是 ",-1)),a(r,{href:"https://opensource.com/%5Bhttps%3A//github.com/alseambusher/crontab-ui%5D%28https%3A//github.com/alseambusher/crontab-ui%29"},{default:s(()=>[...t[7]||(t[7]=[n("crontab-ui",-1)])]),_:1}),t[9]||(t[9]=n("，这是一个用 Node.js 编写的 Web 前端，可以帮助管理 crontab 文件。为了安装和启动 ",-1)),t[10]||(t[10]=o("code",null,"crontab-ui",-1)),t[11]||(t[11]=n(" 供个人使用，我使用了以下命令。",-1))]),t[29]||(t[29]=e(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 做个备份</span></span>
<span class="line"><span>crontab -l &gt; $HOME/crontab-backup</span></span>
<span class="line"><span># 安装 Crontab UI</span></span>
<span class="line"><span>npm install -g crontab-ui</span></span>
<span class="line"><span># 创建本地数据库目录</span></span>
<span class="line"><span>mkdir $HOME/crontab-ui</span></span>
<span class="line"><span># 启动 crontab-ui</span></span>
<span class="line"><span>CRON_DB_PATH=$HOME/crontab-ui crontab-ui</span></span></code></pre></div><p>完成这些后，只需将你的网页浏览器指向 <code>http://localhost:8000</code>，你就会看到 crontab-ui 的网页界面。要做的第一件事是点击 “<ruby>从 Crontab 获取<rt>Get from Crontab</rt></ruby>”，加载你可能有的任何现有作业。然后点击“<ruby>备份<rt>Backup</rt></ruby>”，这样你就可以回滚你所做的任何修改。</p><p><img src="https://opensource.com/sites/default/files/2022-04/Day01-2.png" alt="Image of Crontab-UI"></p><p>添加和编辑 cron 作业是非常简单的。添加一个名称，你想运行的完整命令，以及时间（使用 cron 语法），然后保存。另外，你还可以捕获日志，并设置将工作状态邮寄到你选择的电子邮箱。</p><p>完成后，点击 “<ruby>保存到 Crontab<rt>Save to Crontab</rt></ruby>”。</p><p>我个人非常喜欢它的日志记录功能。有了 crontab-ui，你可以通过点击一个按钮来查看日志，这在排除故障时非常有用。</p><p>我建议不要一直运行 crontab-ui，至少不要公开运行。虽然它确实具有一些基本的身份验证功能，但它不应该暴露在你的本地机器之外。我不需要经常编辑我的 cron 作业，所以我可以按需启动和停止它。</p><p>下次你需要编辑你的 crontab 时，可以试试 crontab-ui！</p><hr>`,9)),o("p",null,[t[13]||(t[13]=n("via: ",-1)),a(r,{href:"https://opensource.com/article/22/5/cron-crontab-ui"},{default:s(()=>[...t[12]||(t[12]=[n("https://opensource.com/article/22/5/cron-crontab-ui",-1)])]),_:1})]),o("p",null,[t[18]||(t[18]=n("作者：",-1)),a(r,{href:"https://opensource.com/users/ksonney"},{default:s(()=>[...t[14]||(t[14]=[n("Kevin Sonney",-1)])]),_:1}),t[19]||(t[19]=n(" 选题：",-1)),a(r,{href:"https://github.com/lkxed"},{default:s(()=>[...t[15]||(t[15]=[n("lkxed",-1)])]),_:1}),t[20]||(t[20]=n(" 译者：",-1)),a(r,{href:"https://github.com/geekpi"},{default:s(()=>[...t[16]||(t[16]=[n("geekpi",-1)])]),_:1}),t[21]||(t[21]=n(" 校对：",-1)),a(r,{href:"https://github.com/wxy"},{default:s(()=>[...t[17]||(t[17]=[n("wxy",-1)])]),_:1})]),o("p",null,[t[24]||(t[24]=n("本文由 ",-1)),a(r,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[22]||(t[22]=[n("LCTT",-1)])]),_:1}),t[25]||(t[25]=n(" 原创编译，",-1)),a(r,{href:"https://linux.cn/"},{default:s(()=>[...t[23]||(t[23]=[n("Linux中国",-1)])]),_:1}),t[26]||(t[26]=n(" 荣誉推出",-1))])])}const y=p(b,[["render",d]]);export{x as __pageData,y as default};
